                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing...
                </>
              ) : isAnalyzingStyle ? (
                 <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Analyzing Style...
                </>
              ) : (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                  </svg>
                  Generate Image
                </>
              )}
            </button>
            {error && (
              <div className="p-4 bg-gray-900 border border-white text-white rounded-lg text-sm">
                {error}
              </div>
            )}

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-white transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-800 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
                        generatedImage === item.imageUrl 
                          ? 'border-white ring-2 ring-white/20' 
                          : 'border-transparent hover:border-gray-600'
                      }`}
                    >
                      <img 
                        src={item.imageUrl} 
                        alt="History item" 
                        className="w-full h-full object-cover" 
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Lightbox Overlay */}
      {isLightboxOpen && generatedImage && (
        <div 
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors bg-gray-900 rounded-full p-2 hover:bg-gray-800 border border-gray-800 z-50"
            onClick={(e) => {
              e.stopPropagation();
              setIsLightboxOpen(false);
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <img 
            src={generatedImage} 
            alt="Full Resolution Result" 
            className="max-w-full max-h-full object-contain shadow-2xl rounded-sm border border-gray-800"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

// Initialize the client
// Using process.env.API_KEY as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes style reference images (or product images) to extract descriptive keywords and infer settings.
 * Uses a text model (Gemini 3 Flash) with JSON schema output.
 * Accepts multiple images.
 */
export const analyzeStyleReference = async (imagesBase64: string[]): Promise<AnalysisResult> => {
  if (imagesBase64.length === 0) {
    return {
      description: "",
      recommendedAspectRatio: "1:1",
      recommendedLighting: "Studio Lighting",
      recommendedPerspective: "Eye Level"
    };
  }

  try {
    const parts: any[] = [];

    // Add all images as parts
    imagesBase64.forEach(base64 => {
      // Clean base64 just in case
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });

    parts.push({
      text: `Analyze the provided images to create a PROFESSIONAL CREATIVE BRIEF.

      1. Deeply analyze the CORE CONCEPT, VISUAL COMPOSITION, LIGHTING, COLORS, PERSPECTIVE, and MOOD.
      2. The goal is to REFINE and ENHANCE the reference's core concept, not to replace it.
      3. Identify the key visual elements that should be preserved and elevated (e.g., specific lighting setup, texture quality, color palette).

      CRITICAL INSTRUCTION:
      - Maintain full depth and quality of analysis.
      - Do not drift away from the reference's original core idea.
      - Your analysis should guide a "Professional Refinement" of the scene, aiming for higher production value while staying true to the source.`
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: { 
              type: Type.STRING, 
              description: "A highly detailed analysis of the visual style, composition, and mood, focusing on how to professionally enhance it." 
            },
            recommendedAspectRatio: { 
              type: Type.STRING, 
              enum: ["1:1", "3:4", "4:3", "9:16", "16:9"],
              description: "The optimal aspect ratio."
            },
            recommendedLighting: { 
              type: Type.STRING, 
              description: "The matching lighting style. Can be a standard term or a custom descriptive phrase."
            },
            recommendedPerspective: { 
              type: Type.STRING, 
              description: "The matching camera perspective. Can be a standard term or a custom descriptive phrase."
            }
          },
          required: ["description", "recommendedAspectRatio", "recommendedLighting", "recommendedPerspective"]
        }
      }
    });

    const text = response.text;
    if (!text) {
       throw new Error("No text response from analysis");
    }

    const json = JSON.parse(text);

    return {
      description: json.description || "",
      recommendedAspectRatio: json.recommendedAspectRatio || "1:1",
      recommendedLighting: json.recommendedLighting || "Studio Lighting",
      recommendedPerspective: json.recommendedPerspective || "Eye Level"
    };

  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return {
      description: "High quality, professional photography with excellent lighting and composition.",
      recommendedAspectRatio: "1:1",
      recommendedLighting: "Studio Lighting",
      recommendedPerspective: "Eye Level"
    };
  }
};

/**
 * Performs a deep visual analysis of reference and product images for scene integration.
 * Used exclusively in OFF: Scene Preserve mode.
 */
export const analyzeSceneStructure = async (
  referenceImagesBase64: string[],
  productImagesBase64: string[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Label and add Reference Images
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });
    parts.push({ text: "Reference Scene Image(s) ^" });

    // Label and add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });
    parts.push({ text: "Product Image(s) ^" });

    parts.push({
      text: `PERFORM A DEEP VISUAL ANALYSIS for SCENE INTEGRATION.

      1. Analyze the REFERENCE SCENE IMAGE(S) specifically for:
         - Lighting (Direction, Hardness/Softness, Color Temperature, Ambient Light)
         - Shadows (Placement, Density, Falloff)
         - Reflections (Surface materials, Environment mapping)
         - Camera Angle & Perspective (Focal length, Horizon line, Camera height)
         - Composition & Scale (Where the subject fits naturally)

      2. Analyze the PRODUCT IMAGE(S) to identify the subject(s) to be integrated.

      3. Output a detailed textual guide for a generative model to seamlessy integrate the product into the scene.
         - Explicitly state how the lighting and shadows should be generated to match the reference.
         - Define the perspective alignment.
         - Ensure the integration is photorealistic and respects the reference environment completely.

      Output the result as a clear, descriptive paragraph suitable for an image generation prompt.`
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
    });

    return response.text || "Analysis failed.";

  } catch (error) {
    console.error("Error analyzing scene structure:", error);
    return "Analysis failed to run. Proceeding with standard generation.";
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 * Supports arrays of product images and optional reference images.
 * Uses the exact prompt string provided by the caller (which now includes all system rules).
 */
export const generateEditedImage = async (
  productImagesBase64: string[],
  prompt: string,
  aspectRatio: string,
  referenceImagesBase64: string[] = []
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add Reference Images (if any)
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add the text prompt last
    parts.push({ text: prompt });

    // Ensure aspectRatio is a valid string for the API, defaulting if it's somehow still "Auto" or invalid
    const validAspectRatios = ["1:1", "3:4", "4:3", "9:16", "16:9"];
    const finalAspectRatio = validAspectRatios.includes(aspectRatio) ? aspectRatio : "1:1";

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: finalAspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import { ImageUpload } from './components/ImageUpload';
