      if (products.length === 0 && styles.length === 0) {
        return;
      }
    }

    setIsAnalyzingStyle(true);
    try {
      const promises: Promise<{type: 'product' | 'style', res: any}>[] = [];

      if (products.length > 0) {
        promises.push(analyzeStyleReference(getCleanBase64s(products)).then(res => ({ type: 'product', res })));
      }

      if (styles.length > 0) {
        promises.push(analyzeStyleReference(getCleanBase64s(styles)).then(res => ({ type: 'style', res })));
      }

      const results = await Promise.all(promises);
      const productRes = results.find(r => r.type === 'product')?.res;
      const styleRes = results.find(r => r.type === 'style')?.res;

      const productText = productRes?.description || (products.length > 0 ? "Analysis pending or unavailable." : "No product images uploaded.");
      const styleText = styleRes?.description || "No style reference provided. Using default creative settings.";

      // Update reference type for prompt logic logic if style reference exists
      if (styleRes && styleRes.referenceType) {
        setStyleReferenceType(styleRes.referenceType);
      } else {
        setStyleReferenceType('PRODUCT'); // Default
      }

      const combinedDesc = `[ PRODUCT SUBJECT ANALYSIS ]\n${productText}\n\n[ STYLE REFERENCE ANALYSIS ]\n${styleText}`;

      setStyleDescription(combinedDesc);

      // Prioritize Style for settings
      const primary = styleRes || productRes;
      if (primary) {
          // Aspect Ratio
          setAspectRatio((current) => current === AspectRatio.AUTO ? primary.recommendedAspectRatio as AspectRatio : current);

          // Lighting
          if (lighting === LightingStyle.AUTO) {
            const lightingValues = Object.values(LightingStyle) as string[];
            if (lightingValues.includes(primary.recommendedLighting)) {
              setLighting(primary.recommendedLighting as LightingStyle);
              setInferredLighting(null);
            } else {
              setInferredLighting(primary.recommendedLighting);
            }
          }

          // Perspective
          if (perspective === CameraPerspective.AUTO) {
            const perspectiveValues = Object.values(CameraPerspective) as string[];
            if (perspectiveValues.includes(primary.recommendedPerspective)) {
              setPerspective(primary.recommendedPerspective as CameraPerspective);
              setInferredPerspective(null);
            } else {
              setInferredPerspective(primary.recommendedPerspective);
            }
          }
      }

    } catch (err) {
      console.error(err);
      setError("Failed to analyze images.");
    } finally {
      setIsAnalyzingStyle(false);
