import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

// Initialize the client
// Using process.env.API_KEY as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes style reference images (or product images) to extract descriptive keywords and infer settings.
 * Uses a text model (Gemini 3 Flash) with JSON schema output.
 * Accepts multiple images.
 */
export const analyzeStyleReference = async (imagesBase64: string[]): Promise<AnalysisResult> => {
  if (imagesBase64.length === 0) {
    return {
      description: "",
      recommendedAspectRatio: "1:1",
      recommendedLighting: "Studio Lighting",
      recommendedPerspective: "Eye Level",
      referenceType: "PRODUCT"
    };
  }

  try {
    const parts: any[] = [];

    // Add all images as parts
    imagesBase64.forEach(base64 => {
      // Clean base64 just in case
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });

    parts.push({
      text: `Analyze the provided images to create a PROFESSIONAL CREATIVE BRIEF.

      STEP 1: DETECT CONTENT TYPE.
      Determine if the image content is primarily:
      - 'PRODUCT': A focused shot of a product (bottle, box, object, device).
      - 'LIFESTYLE': A scene involving people, models, cinematic human moments, or atmosphere where the specific product is secondary or absent.

      STEP 2: ANALYZE ACCORDING TO TYPE.

      [CASE A: LIFESTYLE / PEOPLE / CINEMATIC]
      - DETAILED INTERACTION ANALYSIS: Perform a deep visual analysis of the relationship between the character and the product within the scene.
      - KEY ELEMENTS: Analyze body posture, gaze direction, physical interaction (holding, touching, looking), camera-to-subject distance, camera angle, implied lens type (focal length), depth of field, and cinematic lighting.
      - VISUAL MOOD: Describe the color distribution, atmosphere, and emotional tone.
      - INSTRUCTION FOR GENERATION: The goal is to generate a new professional scene that matches the compositional STRENGTH and INTERACTION logic of the reference.
      - Preserve the cinematic feeling and visual depth.
      - The character and product must be ORGANICALLY INTEGRATED with realistic lighting and shadows. Avoid artificial placement.

      [CASE B: PRODUCT FOCUS]
      - Deeply analyze the CORE CONCEPT, COMPOSITION, LIGHTING, COLORS, PERSPECTIVE.
      - The goal is to REFINE and ENHANCE the reference's core concept.
      - Identify visual elements to preserve and elevate (lighting, texture, colors).
      - Guide a "Professional Refinement" aiming for higher production value while staying true to the source (No drift).

      CRITICAL INSTRUCTION:
      - Maintain full depth and quality of analysis.
      - Output the analysis in the 'description' field based on the detected type.
      - Set 'referenceType' to either 'PRODUCT' or 'LIFESTYLE' based on your detection.`
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: { 
              type: Type.STRING, 
              description: "A highly detailed analysis of the visual style, composition, and mood, tailored to the specific content type (Product vs Lifestyle)." 
            },
            recommendedAspectRatio: { 
              type: Type.STRING, 
              enum: ["1:1", "3:4", "4:3", "9:16", "16:9"],
              description: "The optimal aspect ratio."
            },
            recommendedLighting: { 
              type: Type.STRING, 
              description: "The matching lighting style. Can be a standard term or a custom descriptive phrase."
            },
            recommendedPerspective: { 
              type: Type.STRING, 
              description: "The matching camera perspective. Can be a standard term or a custom descriptive phrase."
            },
            referenceType: {
              type: Type.STRING,
              enum: ["PRODUCT", "LIFESTYLE"],
              description: "Classifies the image as either a 'PRODUCT' focus shot or a 'LIFESTYLE' (people/cinematic) scene."
            }
          },
          required: ["description", "recommendedAspectRatio", "recommendedLighting", "recommendedPerspective", "referenceType"]
        }
      }
    });

    const text = response.text;
    if (!text) {
       throw new Error("No text response from analysis");
    }

    const json = JSON.parse(text);

    return {
      description: json.description || "",
      recommendedAspectRatio: json.recommendedAspectRatio || "1:1",
      recommendedLighting: json.recommendedLighting || "Studio Lighting",
      recommendedPerspective: json.recommendedPerspective || "Eye Level",
      referenceType: json.referenceType || "PRODUCT"
    };

  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return {
      description: "High quality, professional photography with excellent lighting and composition.",
      recommendedAspectRatio: "1:1",
      recommendedLighting: "Studio Lighting",
      recommendedPerspective: "Eye Level",
      referenceType: "PRODUCT"
    };
  }
};

/**
 * Performs a deep visual analysis of reference and product images for scene integration.
 * Used exclusively in OFF: Scene Preserve mode.
 */
export const analyzeSceneStructure = async (
  referenceImagesBase64: string[],
  productImagesBase64: string[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Label and add Reference Images
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });
    parts.push({ text: "Reference Scene Image(s) ^" });

    // Label and add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });
    parts.push({ text: "Product Image(s) ^" });

    parts.push({
      text: `PERFORM A DEEP AND PRECISE VISUAL ANALYSIS for SCENE INTEGRATION.

      1. REFERENCE SCENE ANALYSIS (DEEP DIVE):
         - PRODUCT POSITIONING: Accurately identify where the product currently sits or is intended to sit.
         - ENVIRONMENT INTERACTION: Analyze how objects interact with the table/floor/surrounding. Look for contact shadows, ambient occlusion, and reflections.
         - LIGHTING & PHYSICS: Determine the exact light direction, shadow fallout, and color temperature.
         - CAMERA & DEPTH: Analyze the perspective, focal length, and depth of field to ensure the new product matches the lens characteristics.
         - SURFACE MATERIALS: Identify textures (wood, marble, cloth) to simulate correct reflections and friction.

      2. PRODUCT ANALYSIS: Identify the subject(s) to be integrated.

      3. INTEGRATION GUIDE:
         - Output a detailed directive for regenerating the scene with the new product.
         - EMPHASIS: The integration must be HYPER-REALISTIC. No cut-and-paste.
         - The product must feel like it was present during the original shot, respecting all lighting and physical constraints of the reference scene.

      Output the result as a clear, descriptive paragraph suitable for a high-end generative model prompt.`
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
    });

    return response.text || "Analysis failed.";

  } catch (error) {
    console.error("Error analyzing scene structure:", error);
    return "Analysis failed to run. Proceeding with standard generation.";
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 * Supports arrays of product images and optional reference images.
 * Uses the exact prompt string provided by the caller (which now includes all system rules).
 */
export const generateEditedImage = async (
  productImagesBase64: string[],
  prompt: string,
  aspectRatio: string,
  referenceImagesBase64: string[] = []
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add Reference Images (if any)
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add the text prompt last
    parts.push({ text: prompt });

    // Ensure aspectRatio is a valid string for the API, defaulting if it's somehow still "Auto" or invalid
    const validAspectRatios = ["1:1", "3:4", "4:3", "9:16", "16:9"];
    const finalAspectRatio = validAspectRatios.includes(aspectRatio) ? aspectRatio : "1:1";

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: finalAspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

